class Solution:
    def removeOuterParentheses(self, s: str) -> str:
        res = []
        depth = 0                          # number of currently unmatched '('
        for ch in s:                       # single pass: O(n)
            if ch == "(":
                if depth > 0:              # an inner '(' is kept; the outer one opens at depth 0
                    res.append(ch)
                depth += 1
            else:
                depth -= 1
                if depth > 0:              # an inner ')' is kept; the outer one closes back to depth 0
                    res.append(ch)
        return "".join(res)

